#include "sblr_sec_deauthenticate_runtime.hpp"
#include <cstring>
namespace scratchbird::engine::sblr{namespace{void w(std::vector<uint8_t>&b,size_t p,uint64_t v,int n){for(int i=0;i<n;i++)b[p+i]=v>>(8*i);}uint64_t r(const uint8_t*p,size_t x){uint64_t v=0;for(int i=0;i<8;i++)v|=uint64_t(p[x+i])<<(8*i);return v;}void c(std::vector<uint8_t>&b,size_t p,const void*x,size_t n){memcpy(b.data()+p,x,n);}bool h(const uint8_t*p,size_t n,const char*m){return p&&n==64&&!memcmp(p,m,4)&&p[4]==1;}}
std::vector<uint8_t>EncodeSblrSecDedeauthenticateRequestV1(const SblrSecDedeauthenticateRequestV1&v){std::vector<uint8_t>b(64);c(b,0,"SADQ",4);w(b,4,1,2);w(b,6,64,2);w(b,8,64,4);c(b,16,v.receipt.data(),16);w(b,32,v.occurrence,8);return b;}bool DecodeSblrSecDedeauthenticateRequestV1(const uint8_t*p,size_t n,SblrSecDedeauthenticateRequestV1*o,std::string*d){if(!o||!h(p,n,"SADQ")){if(d)*d="SADQ invalid";return false;}memcpy(o->receipt.data(),p+16,16);o->occurrence=r(p,32);return o->occurrence!=0;}
std::vector<uint8_t>EncodeSblrSecDedeauthenticateDescriptorV1(const SblrSecDedeauthenticateDescriptorV1&v,bool op){std::vector<uint8_t>b(128);c(b,0,op?"SADO":"SADD",4);w(b,4,1,2);w(b,6,128,2);w(b,8,128,4);c(b,16,v.principal_uuid.data(),16);w(b,32,v.expected_generation,8);w(b,40,v.security_generation,8);w(b,48,v.availability,8);c(b,56,v.evidence.data(),16);return b;}bool DecodeSblrSecDedeauthenticateDescriptorV1(const uint8_t*p,size_t n,SblrSecDedeauthenticateDescriptorV1*o,std::string*d,bool op){if(!o||n!=128||memcmp(p,op?"SADO":"SADD",4)){if(d)*d="SAD descriptor invalid";return false;}memcpy(o->principal_uuid.data(),p+16,16);o->expected_generation=r(p,32);o->security_generation=r(p,40);o->availability=r(p,48);memcpy(o->evidence.data(),p+56,16);return o->availability!=0;}
std::vector<uint8_t>EncodeSblrSecDedeauthenticateResultV1(const SblrSecDedeauthenticateResultV1&v){std::vector<uint8_t>b(128);c(b,0,"SADR",4);w(b,4,1,2);w(b,6,128,2);w(b,8,128,4);b[16]=v.status;b[17]=v.publication_barrier;c(b,24,v.principal_uuid.data(),16);w(b,40,v.generation,8);w(b,48,v.security_generation,8);w(b,56,v.availability,8);c(b,64,v.effect_evidence.data(),32);return b;}bool DecodeSblrSecDedeauthenticateResultV1(const uint8_t*p,size_t n,SblrSecDedeauthenticateResultV1*o,std::string*d){if(!o||n!=128||memcmp(p,"SADR",4)){if(d)*d="SADR invalid";return false;}o->status=p[16];o->publication_barrier=p[17];memcpy(o->principal_uuid.data(),p+24,16);o->generation=r(p,40);o->security_generation=r(p,48);o->availability=r(p,56);memcpy(o->effect_evidence.data(),p+64,32);return true;}}
